"""Append-only user choices; revisions and identifiers are generated by Product."""

from datetime import datetime
from uuid import UUID

from sqlalchemy import CheckConstraint, DateTime, ForeignKey, Index, Integer, String, Uuid, text
from sqlalchemy.orm import Mapped, mapped_column

from app.database.base import Base


class ProductDeadlineExitChoiceModel(Base):
    __tablename__ = "product_deadline_exit_choices"
    __table_args__ = (
        Index(
            "uq_product_deadline_exit_choice_root",
            "workspace_id",
            "warrant_id",
            unique=True,
            postgresql_where=text("previous_revision_id IS NULL"),
            sqlite_where=text("previous_revision_id IS NULL"),
        ),
        Index(
            "uq_product_deadline_exit_choice_number",
            "workspace_id",
            "warrant_id",
            "revision_number",
            unique=True,
        ),
        Index("uq_product_deadline_exit_choice_successor", "previous_revision_id", unique=True),
        CheckConstraint("revision_number > 0", name="product_deadline_exit_choice_positive"),
        CheckConstraint(
            "(listing_id IS NULL AND listing_version IS NULL AND trading_venue_id IS NULL "
            "AND venue_mic IS NULL AND venue_version IS NULL AND quotation_currency_code IS NULL) "
            "OR (listing_id IS NOT NULL AND listing_version IS NOT NULL AND listing_version > 0 "
            "AND trading_venue_id IS NOT NULL AND venue_mic IS NOT NULL "
            "AND venue_version IS NOT NULL AND venue_version > 0 "
            "AND quotation_currency_code IS NOT NULL)",
            name="product_deadline_exit_choice_shape",
        ),
    )
    id: Mapped[UUID] = mapped_column(Uuid(), primary_key=True)
    workspace_id: Mapped[UUID] = mapped_column(ForeignKey("workspaces.id", ondelete="RESTRICT"))
    warrant_id: Mapped[UUID] = mapped_column(ForeignKey("warrants.id", ondelete="RESTRICT"))
    previous_revision_id: Mapped[UUID | None] = mapped_column(
        ForeignKey("product_deadline_exit_choices.id", ondelete="RESTRICT")
    )
    revision_number: Mapped[int] = mapped_column(Integer())
    terms_id: Mapped[UUID] = mapped_column(
        ForeignKey("warrant_terms_versions.id", ondelete="RESTRICT")
    )
    listing_id: Mapped[UUID | None] = mapped_column(
        ForeignKey("warrant_listings.id", ondelete="RESTRICT")
    )
    listing_version: Mapped[int | None] = mapped_column(Integer())
    trading_venue_id: Mapped[UUID | None] = mapped_column(
        ForeignKey("trading_venues.id", ondelete="RESTRICT")
    )
    venue_mic: Mapped[str | None] = mapped_column(String(4))
    venue_version: Mapped[int | None] = mapped_column(Integer())
    quotation_currency_code: Mapped[str | None] = mapped_column(String(3))
    recorded_at: Mapped[datetime] = mapped_column(DateTime(timezone=True))
    recorded_by: Mapped[UUID] = mapped_column(Uuid())
